//! TypeScript types from the session API's JSON Schema (`specs/session.schema.json`): every
//! definition, every method's params and result, every notification, and the error codes, for
//! the web client (`web/client`). Covers the subset of JSON Schema the protocol types produce.

use std::fmt::Write as _;

use serde_json::{Map, Value};

/// The header of the generated file.
const HEADER: &str = "\
// The session API's types (specs/session.md), generated by `cargo xtask schema` from
// specs/session.schema.json, itself generated from the Rust protocol types. Do not edit.

";

/// The TypeScript module for `schema`, or what in it could not be read.
pub fn module(schema: &Value) -> Result<String, String> {
    let mut out = String::from(HEADER);
    let protocol = schema["protocol"]
        .as_str()
        .ok_or("the schema names no protocol version")?;
    let _ = writeln!(out, "/** The protocol version these types describe. */");
    let _ = writeln!(
        out,
        "export const PROTOCOL = {};\n",
        literal(&protocol.into())
    );

    for (name, definition) in sorted(object(schema, "$defs")?) {
        definition_of(&mut out, name, definition);
    }
    if let Some(error) = schema.get("error") {
        let _ = writeln!(
            out,
            "/** A JSON-RPC error object, as any failed request answers. */\nexport type ErrorObject = {};\n",
            ty(error, 0)
        );
    }

    methods(&mut out, object(schema, "methods")?)?;
    notifications(&mut out, object(schema, "notifications")?);
    errors(&mut out, object(schema, "errors")?)?;
    Ok(out)
}

/// Each method's params and result, the `Methods` table, and which methods stream.
fn methods(out: &mut String, methods: &Map<String, Value>) -> Result<(), String> {
    let mut table = String::new();
    let mut streaming = Vec::new();
    for (method, described) in sorted(methods) {
        let base = pascal(method);
        let params = described
            .get("params")
            .ok_or(format!("{method} has no params"))?;
        let result = described
            .get("result")
            .ok_or(format!("{method} has no result"))?;
        definition_of(out, &format!("{base}Params"), params);
        definition_of(out, &format!("{base}Result"), result);
        let _ = writeln!(
            table,
            "  readonly {}: {{ readonly params: {base}Params; readonly result: {base}Result }};",
            literal(&method.as_str().into())
        );
        if described["streams"].as_bool() == Some(true) {
            streaming.push(literal(&method.as_str().into()));
        }
    }
    let _ = writeln!(
        out,
        "/** Every method, with its params and result. */\nexport interface Methods {{\n{table}}}\n"
    );
    let _ = writeln!(out, "export type Method = keyof Methods;\n");
    let _ = writeln!(
        out,
        "/** The methods that answer with server-sent events, unless run in the background. */\nexport const STREAMING = [{}] as const;\n",
        streaming.join(", ")
    );
    let _ = writeln!(
        out,
        "export type StreamingMethod = (typeof STREAMING)[number];\n"
    );
    Ok(())
}

/// Each notification's params, and the `Notification` union.
fn notifications(out: &mut String, notifications: &Map<String, Value>) {
    let mut notes = Vec::new();
    for (method, params) in sorted(notifications) {
        let name = format!("{}Params", pascal(method));
        definition_of(out, &name, params);
        notes.push(format!(
            "  | {{ readonly jsonrpc: \"2.0\"; readonly method: {}; readonly params: {name} }}",
            literal(&method.as_str().into())
        ));
    }
    let _ = writeln!(
        out,
        "/** What a server sends while a turn runs or a client watches. */\nexport type Notification =\n{};\n",
        notes.join("\n")
    );
}

/// The `ErrorCode` table.
fn errors(out: &mut String, errors: &Map<String, Value>) -> Result<(), String> {
    let mut codes = String::new();
    for (name, error) in sorted(errors) {
        let code = error["code"]
            .as_i64()
            .ok_or(format!("error {name} has no code"))?;
        let message = error["message"].as_str().unwrap_or_default();
        let _ = writeln!(codes, "  /** {} */\n  {name}: {code},", comment(message));
    }
    let _ = write!(
        out,
        "/** The error codes a request may be answered with. */\nexport const ErrorCode = {{\n{codes}}} as const;\n"
    );
    Ok(())
}

fn object<'a>(schema: &'a Value, key: &str) -> Result<&'a Map<String, Value>, String> {
    schema
        .get(key)
        .and_then(Value::as_object)
        .ok_or_else(|| format!("the schema has no {key}"))
}

fn sorted(map: &Map<String, Value>) -> Vec<(&String, &Value)> {
    let mut entries: Vec<_> = map.iter().collect();
    entries.sort_by(|a, b| a.0.cmp(b.0));
    entries
}

/// `export type <name> = ...;`, with the definition's description as its comment.
fn definition_of(out: &mut String, name: &str, schema: &Value) {
    if let Some(description) = schema.get("description").and_then(Value::as_str) {
        let _ = writeln!(out, "{}", doc(description, 0));
    }
    let _ = writeln!(out, "export type {name} = {};\n", ty(schema, 0));
}

/// `thread/start` as `ThreadStart`.
fn pascal(method: &str) -> String {
    method
        .split(['/', '_', '.'])
        .map(|word| {
            let mut chars = word.chars();
            chars.next().map_or_else(String::new, |first| {
                first.to_uppercase().chain(chars).collect()
            })
        })
        .collect()
}

fn literal(value: &Value) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| "never".to_owned())
}

fn comment(text: &str) -> String {
    text.replace("*/", "*\\/")
}

/// A JSDoc comment at `depth`.
fn doc(text: &str, depth: usize) -> String {
    let pad = "  ".repeat(depth);
    let lines: Vec<&str> = text.lines().collect();
    if lines.len() == 1 {
        return format!("{pad}/** {} */", comment(text));
    }
    let mut out = format!("{pad}/**\n");
    for line in lines {
        let _ = writeln!(out, "{pad} * {}", comment(line).trim_end());
    }
    let _ = write!(out, "{pad} */");
    out
}

/// The TypeScript type of `schema`, written at nesting `depth`.
fn ty(schema: &Value, depth: usize) -> String {
    let Some(fields) = schema.as_object() else {
        return if schema.as_bool() == Some(false) {
            "never".to_owned()
        } else {
            "unknown".to_owned()
        };
    };
    if let Some(reference) = fields.get("$ref").and_then(Value::as_str) {
        return reference.rsplit('/').next().unwrap_or("unknown").to_owned();
    }
    if let Some(constant) = fields.get("const") {
        return literal(constant);
    }
    if let Some(values) = fields.get("enum").and_then(Value::as_array) {
        return union(values.iter().map(literal).collect());
    }
    for key in ["oneOf", "anyOf"] {
        if let Some(cases) = fields.get(key).and_then(Value::as_array) {
            return union(cases.iter().map(|case| ty(case, depth)).collect());
        }
    }
    if let Some([only]) = fields
        .get("allOf")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
    {
        return ty(only, depth);
    }
    match fields.get("type") {
        Some(Value::String(kind)) => typed(kind, fields, depth),
        Some(Value::Array(kinds)) => union(
            kinds
                .iter()
                .filter_map(Value::as_str)
                .map(|kind| typed(kind, fields, depth))
                .collect(),
        ),
        _ => "unknown".to_owned(),
    }
}

fn typed(kind: &str, fields: &Map<String, Value>, depth: usize) -> String {
    match kind {
        "string" => "string".to_owned(),
        "integer" | "number" => "number".to_owned(),
        "boolean" => "boolean".to_owned(),
        "null" => "null".to_owned(),
        "array" => {
            let item = fields
                .get("items")
                .map_or_else(|| "unknown".to_owned(), |items| ty(items, depth));
            format!("readonly ({item})[]")
        }
        "object" => object_type(fields, depth),
        _ => "unknown".to_owned(),
    }
}

fn object_type(fields: &Map<String, Value>, depth: usize) -> String {
    let properties = fields.get("properties").and_then(Value::as_object);
    let extra = fields.get("additionalProperties");
    let Some(properties) = properties.filter(|properties| !properties.is_empty()) else {
        return match extra {
            Some(Value::Object(schema)) if !schema.is_empty() => {
                format!(
                    "{{ readonly [key: string]: {} }}",
                    ty(&Value::Object(schema.clone()), depth)
                )
            }
            Some(Value::Bool(true) | Value::Object(_)) => {
                "{ readonly [key: string]: unknown }".to_owned()
            }
            _ => "Readonly<Record<string, never>>".to_owned(),
        };
    };
    let required: Vec<&str> = fields
        .get("required")
        .and_then(Value::as_array)
        .map(|names| names.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let pad = "  ".repeat(depth + 1);
    let mut out = String::from("{\n");
    for (name, property) in sorted(properties) {
        if let Some(description) = property.get("description").and_then(Value::as_str) {
            let _ = writeln!(out, "{}", doc(description, depth + 1));
        }
        let optional = if required.contains(&name.as_str()) {
            ""
        } else {
            "?"
        };
        let key = if name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
            && !name.starts_with(|c: char| c.is_ascii_digit())
        {
            name.clone()
        } else {
            literal(&Value::String(name.clone()))
        };
        let _ = writeln!(
            out,
            "{pad}readonly {key}{optional}: {};",
            ty(property, depth + 1)
        );
    }
    out.push_str(&"  ".repeat(depth));
    out.push('}');
    out
}

fn union(mut cases: Vec<String>) -> String {
    cases.dedup();
    match cases.len() {
        0 => "never".to_owned(),
        1 => cases.swap_remove(0),
        _ => cases.join(" | "),
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn schemas_become_readonly_types() {
        let object = json!({
            "type": "object",
            "properties": {
                "id": {"$ref": "#/$defs/ThreadId"},
                "limit": {"type": ["integer", "null"]},
                "tags": {"type": "array", "items": {"type": "string"}},
                "kind": {"oneOf": [{"const": "a"}, {"const": "b"}]}
            },
            "required": ["id", "kind"]
        });
        assert_eq!(
            ty(&object, 0),
            "{\n  readonly id: ThreadId;\n  readonly kind: \"a\" | \"b\";\n  \
             readonly limit?: number | null;\n  readonly tags?: readonly (string)[];\n}"
        );
        assert_eq!(
            ty(&json!({"type": "object"}), 0),
            "Readonly<Record<string, never>>"
        );
        assert_eq!(
            ty(&json!({"type": "object", "additionalProperties": true}), 0),
            "{ readonly [key: string]: unknown }"
        );
        assert_eq!(ty(&json!(true), 0), "unknown");
        assert_eq!(pascal("thread/start"), "ThreadStart");
        assert_eq!(pascal("turn/live"), "TurnLive");
    }
}
